  /**
   * ISO 8601 hard deadline the runtime enforces against.
   */
  deadline?: string;
  created_at: string;
  updated_at: string;
  /**
   * Set when the status first leaves `draft`.
   */
  started_at?: string;
  /**
   * Set when the status becomes terminal.
   */
